#include "Updater.h"
#include <QJsonDocument>
#include <QJsonArray>
#include <QStandardPaths>
#include <QDir>
#include <QDesktopServices>
#include <QFileInfo>
#include <QTimer>

namespace gs {
QNetworkRequest Updater::request(QUrl url)const{QNetworkRequest r(url);r.setRawHeader("User-Agent","GlassStats-Qt-Updater/0.2.0");r.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::NoLessSafeRedirectPolicy);r.setTransferTimeout(600000);return r;}
void Updater::fail(QString error){status_=error;busy_=false;progress_=0;if(output_){output_->close();output_->remove();output_.reset();}hash_.reset();reply_=nullptr;emit changed();}
void Updater::check(bool beta){if(busy_)return;busy_=true;status_="Checking GitHub…";emit changed();auto reply=network_.get(request(QUrl("https://api.github.com/repos/eduardojsborges/GlassStats-Qt/releases?per_page=100")));reply_=reply;connect(reply,&QNetworkReply::finished,this,[this,reply,beta]{if(reply_!=reply){reply->deleteLater();return;}reply_=nullptr;busy_=false;if(reply->error()!=QNetworkReply::NoError){status_="Update check unavailable: "+reply->errorString();}else{auto doc=QJsonDocument::fromJson(reply->readAll());release_=selectRelease(doc.array(),GLASSSTATS_VERSION,beta,platformKey());status_=release_?"New version available: "+release_->tag:"You have the latest version for this platform/channel.";}reply->deleteLater();emit changed();emit checkFinished();});}
void Updater::download(){if(busy_||!release_)return;expected_=release_->digest.toLower();if(expected_.startsWith("sha256:"))expected_.remove(0,7);QRegularExpression digest("^[a-f0-9]{64}$");if(digest.match(expected_).hasMatch()){downloadAsset();return;}if(release_->checksumUrl.isEmpty()){fail("This release has no SHA-256 checksum. Nothing was downloaded.");return;}busy_=true;status_="Reading release checksum…";emit changed();auto reply=network_.get(request(QUrl(release_->checksumUrl)));reply_=reply;connect(reply,&QNetworkReply::finished,this,[this,reply]{if(reply_!=reply){reply->deleteLater();return;}reply_=nullptr;if(reply->error()!=QNetworkReply::NoError){auto e=reply->errorString();reply->deleteLater();fail(e);return;}auto text=QString::fromUtf8(reply->read(65536));auto pattern=QRegularExpression("(?m)^([a-fA-F0-9]{64})[ \\t]+\\*?"+QRegularExpression::escape(release_->assetName)+"\\s*$");auto m=pattern.match(text);reply->deleteLater();if(!m.hasMatch()){fail("Invalid release checksum; nothing was installed.");return;}expected_=m.captured(1).toLower();downloadAsset();});}
void Updater::downloadAsset(){if(!release_)return;busy_=true;progress_=0;status_="Downloading verified update…";auto dir=QStandardPaths::writableLocation(QStandardPaths::CacheLocation)+"/updates";QDir().mkpath(dir);path_=dir+"/"+release_->assetName;output_=std::make_unique<QFile>(path_+".partial");if(!output_->open(QIODevice::WriteOnly)){fail(output_->errorString());return;}hash_=std::make_unique<QCryptographicHash>(QCryptographicHash::Sha256);auto reply=network_.get(request(QUrl(release_->assetUrl)));reply_=reply;connect(reply,&QNetworkReply::readyRead,this,[this,reply]{if(reply_!=reply||!output_)return;auto bytes=reply->readAll();if(output_->size()+bytes.size()>2ll*1024*1024*1024||output_->write(bytes)!=bytes.size()){reply->abort();return;}hash_->addData(bytes);});connect(reply,&QNetworkReply::downloadProgress,this,[this](qint64 received,qint64 total){progress_=total>0?double(received)/total:-1;emit changed();});connect(reply,&QNetworkReply::finished,this,[this,reply]{if(reply_!=reply){reply->deleteLater();return;}auto bytes=reply->readAll();if(!bytes.isEmpty()){output_->write(bytes);hash_->addData(bytes);}auto error=reply->error();auto errorText=reply->errorString();reply->deleteLater();reply_=nullptr;if(error!=QNetworkReply::NoError){fail("Download stopped: "+errorText);return;}auto actual=QString::fromLatin1(hash_->result().toHex());if(actual!=expected_){fail("SHA-256 verification failed. Nothing was installed.");return;}output_->close();QFile::remove(path_);if(!QFile::rename(path_+".partial",path_)){fail("Could not finalize the verified download.");return;}output_.reset();hash_.reset();busy_=false;progress_=1;status_="Verified download ready. Installation is interactive; your current app continues running.";emit changed();emit installerReady(path_);});emit changed();}
void Updater::cancel(){if(reply_){auto r=reply_;reply_=nullptr;r->abort();r->deleteLater();}fail("Update operation canceled. Monitoring continues.");}
void Updater::openRelease(){if(release_)QDesktopServices::openUrl(QUrl(release_->page));}
}
